def syllabus(name):
 subj='chem' if name.startswith('chem') else 'bio'
 ids=['C8-IQ1-02'] if name=='chem-m8-p03' else ['C8-IQ1-04','C8-IQ1-01'] if name=='chem-m8-g02' else ['C8-IQ1-04'] if subj=='chem' else ['B8-IQ1-02'] if name=='bio-m8-p02' else ['B8-IQ2-01']
 ledger=json.loads((B.parent/'programme/syllabus'/f'{subj}-2017-y12.json').read_text(encoding='utf-8'))
 def walk(o):
  if isinstance(o,dict):
   if o.get('id') in ids:yield o
   for v in o.values():yield from walk(v)
  elif isinstance(o,list):
   for v in o:yield from walk(v)
 official=json.loads((A/'brief117-official-syllabus.json').read_text(encoding='utf-8'))[subj]['text']
 norm=lambda s:re.sub(r'\s+',' ',s).strip()
 checks=[]
 for item in walk(ledger):
  tests=[item['text']]+item.get('examples',[])
  ok=all(norm(t) in norm(official) for t in tests)
  checks.append(f"{item['id']}: exact parent wording and {len(tests)-1} listed examples "+('match the downloaded official DOCX after whitespace normalisation.' if ok else 'do not all match verbatim; see machine comparison.'))
 return ' '.join(checks)+' Official DOCX URL and SHA-256 are in `../assets/brief117-official-syllabus.json`. The local identifiers are catalogue labels, not printed NESA codes. Biological subset quotes must keep the parent and intended bullet distinct; the designs do that. Watching a practical does not establish that the student conducted it.'

summary={}
for key,r in R.items():
 info=audit[r['file']]
 common=f"Reviewer: independent AI reviewer, 30 October 2026. Did not author the design. Input: `../lessons/{r['file']}.md`, Revision 1, exact SHA-256 `{info['sha256']}`. Reviewed the written narration, planned visuals, attempts, numerical notes and metadata. No actual lesson stills, continuous playback, recorded audio or export was reviewed. Human listening, motion at playback speed and real student learning evidence remain pending. This is not recording or release approval."
 counts=', '.join(str(s['characters']) for s in info['scenes'])
 mechanics=f"Narration independently recounted from > lines, bold markers removed and lines joined within each scene: **{info['total_characters']:,} characters**, {len(info['scenes'])} scenes. Per-scene counts: {counts}. U+2014 count: {info['em_dashes']}. The script-count and stated duration are estimates, not measured speech timing."
 for kind,kindtitle,suffix in [('learning','learning review','learning-review'),('science','science check','claude-science-check')]:
  findings=r[kind]; nblock=sum(f[0]=='blocker' for f in findings); nshould=sum(f[0]=='should fix' for f in findings)
  t=f"# {key} {kindtitle}\n\n{common}\n\n{mechanics}\n\n"
  if kind=='learning':
   t+=f"Main question: {r['question']}\n\nConcrete trace from the stated entry knowledge: {r['trace']}\n\n## Keep\n\n{r['keep']}\n\n## Boundaries and overlap\n\n{r['overlap']}\n\n"
  else:
   t+='## Verification and recalculation\n\n'+r['verified']+'\n\nIndependent machine arithmetic for 52 records is saved in `../assets/brief117-numerical-audit.json`, generated by `docs/production/claude-pm/assets/brief116-121-tools/brief117-numbers.py`.\n\n'
   if key=='m8c04':t+='Primary-literature follow-up: the ACS copper-ammonia colorimetry experiment reports a calibration at 600 nm with a method-specific slope of 42.7 L mol^-1 cm^-1, supporting a value of the order of 50 and stronger absorption than hydrated copper. A primary Sensors study places the aqueous copper band near 800 nm. Neither establishes one universal exact epsilon for all reagent conditions; retain the measured calibration rather than treating the author-note constants as certified instrument values.\n\n'
   t+='## Syllabus wording\n\n'+syllabus(r['file'])+'\n\n'
  t+='## Findings\n\n'
  for i,(severity,scene,quote,problem,repair) in enumerate(findings,1):
   t+=f"### {i}. {severity}: {scene}\n\nText: \"{quote}\"\n\n{problem}\n\nRepair: {repair}\n\n"
  t+=f"Counts: **{nblock} blocker; {nshould} should fix; 0 optional**. Findings repeated between the two reviews describe the same issues and must not be added as separate defects.\n\n"
  if kind=='learning':
   t+='## Checks and remaining limits\n\nThe planned questions are exam-style constructed responses, with full cards and countdowns after the spoken prompt. Existing visual plans use apparatus, tissue or data and show changes on named cues; those are useful plans, not playback evidence. Quiet book notes are separate from new reasoning. No unsupported claim of a motion pass is made.\n\n'
   t+='The routine worked-calculation repairs preserve task, equation, units and earlier necessary results. All fourteen official 2019-to-2025 Chemistry and Biology papers were downloaded and searched; relevant question contexts were compared. No close paraphrase was found. The exact comparison and limits for image-only material are in `../assets/brief117-near-match-review.md`. Similar scientific moves and dilution ratios alone do not prove copying; this is not a universal originality guarantee.\n\n'
   if key in ['m8p03','m8c04','m8p04','m8p02b']:t+='Timing: the design is near the 570-second cap. Apply the paired cuts named with repairs, then recount and time the exact voiced revision. Do not solve extra detail by shrinking text or rushing speech.\n\n'
   if key=='m8b08':t+='Length: only 13 characters above the 5,500 floor. Reallocate the repeated iron words to needed causal explanation; recount the full revision, rather than padding or deleting a whole scene without replacement.\n\n'
  else:
   t+='## Sources and limits\n\nSources checked online 30 October 2026. Author-only numeric estimates explicitly marked unverified above remain unverified. Site quotations and hashes are in `../assets/brief117-site-evidence.json`; proposed additions, confirmations and rejected suggestions are in `../assets/brief117-site-corrections-proposed.md`. Exact product SDS checks remain incomplete where stated. All fourteen official 2019-to-2025 papers were searched and relevant stems compared in `../assets/brief117-near-match-review.md`; no close paraphrase found, with image-only-text limits recorded. Asset inspection is a separate provenance record and cannot be inferred from this source review.\n\n'
   t+='\n'.join('- '+link(k) for k in r['sources'])+'\n\n'
  t+='## Resolution\n'
  if chr(8212) in t:raise ValueError('em dash')
  (C/f'{key}-{suffix}.md').write_text(t,encoding='utf-8')
  summary.setdefault(key,{})[kind]={'blockers':nblock,'should_fix':nshould}
(A/'brief117-review-counts.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
print(json.dumps(summary,indent=2))
